import sys
from collections import deque
sys.setrecursionlimit(10**7)
MOD = 10**9 + 7

def get_factor(num, f):
    cnt = 0
    while num % f == 0:
        cnt += 1
        num //= f
    return cnt

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    a = [0] * (n + 1)
    for i in range(1, n + 1):
        a[i] = int(next(it))
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(it)); v = int(next(it))
        adj[u].append(v)
        adj[v].append(u)

    dp = [[0] * 4 for _ in range(n + 1)]
    ans = 0
    # stack elements: (node, parent, visited_flag)
    stack = [(1, -1, False)]

    while stack:
        u, p, vis = stack.pop()
        if not vis:
            # compute current node state
            cnt2 = get_factor(a[u], 2)
            cnt5 = get_factor(a[u], 5)
            has2 = 1 if cnt2 >= 1 else 0
            has5 = 1 if cnt5 >= 1 else 0
            state = (has2 << 1) | has5
            # reset dp[u]
            dp[u] = [0] * 4
            dp[u][state] = 1
            # push for post-order
            stack.append((u, p, True))
            # push children
            for v in adj[u]:
                if v == p:
                    continue
                stack.append((v, u, False))
        else:
            # merge children's dp
            for v in adj[u]:
                if v == p:
                    continue
                tmp = [0] * 4
                for i in range(4):
                    if dp[u][i] == 0:
                        continue
                    for j in range(4):
                        if dp[v][j] == 0:
                            continue
                        k = i | j
                        tmp[k] = (tmp[k] + dp[u][i] * dp[v][j]) % MOD
                for k in range(4):
                    dp[u][k] = (dp[u][k] + tmp[k]) % MOD
            # add to answer
            ans = (ans + dp[u][3]) % MOD

    print(ans)

if __name__ == '__main__':
    main()
