import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static final int MAXN = 100005;
    static List<Integer>[] adj = new ArrayList[MAXN];
    static long[][] dp = new long[MAXN][4];
    static int[] a = new int[MAXN];

    // 计算num中f因子的个数
    static int getFactor(int num, int f) {
        int cnt = 0;
        while (num % f == 0) {
            cnt++;
            num /= f;
        }
        return cnt;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();

        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            adj[u].add(v);
            adj[v].add(u);
        }

        // 栈模拟DFS
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[] { 1, -1, 0 });  // 初始节点为1，父节点为-1，未访问
        long ans = 0;

        while (!stack.isEmpty()) {
            int[] node = stack.pop();
            int u = node[0], p = node[1], vis = node[2];

            if (vis == 0) {
                int cnt2 = getFactor(a[u], 2);
                int cnt5 = getFactor(a[u], 5);
                boolean has2 = cnt2 >= 1;
                boolean has5 = cnt5 >= 1;
                int state = (has2 ? 2 : 0) | (has5 ? 1 : 0);
                Arrays.fill(dp[u], 0);
                dp[u][state] = 1;

                stack.push(new int[] { u, p, 1 });
                for (int v : adj[u]) {
                    if (v != p) {
                        stack.push(new int[] { v, u, 0 });
                    }
                }
            } else {
                for (int v : adj[u]) {
                    if (v != p) {
                        long[] tmp = new long[4];
                        for (int i = 0; i < 4; i++) {
                            for (int j = 0; j < 4; j++) {
                                int k = i | j;
                                tmp[k] = (tmp[k] + dp[u][i] * dp[v][j]) % MOD;
                            }
                        }
                        for (int k = 0; k < 4; k++) {
                            dp[u][k] = (dp[u][k] + tmp[k]) % MOD;
                        }
                    }
                }
                ans = (ans + dp[u][3]) % MOD;
            }
        }

        System.out.println(ans);
    }
}
